    // Allocate space for the local variables
    if (localVars == null) {
        localVars = new LocalVariable[numLocal];
    } else {
        localVars = Arrays.copyOf(localVars, localVars.length + numLocal);
    }

    // Allocate space for the stack elements
    if (stackValues == null) {
        stackValues = new Object[numStack];
    } else {
        stackValues = Arrays.copyOf(stackValues, stackValues.length + numStack);
    }

    // Update the frame with the new information
    currentFrame.setLocalVariableCount(numLocal);
    currentFrame.setNextWriteSlot(nextIndex);
    currentFrame.setLocalVariableStore(localVars);
    currentFrame.setStackValueStore(stackValues);

    return nextIndex;
}
