void insertBefore(Bucket bucket){
    // Check if the bucket is valid
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    // Check if this bucket is the first one
    if (this.head == bucket) {
        throw new IllegalArgumentException("Cannot insert before the head bucket");
    }
    // Find the previous bucket before the given bucket
    Bucket previousBucket = this.head;
    while (previousBucket.next != bucket) {
        previousBucket = previousBucket.next;
    }

    // Insert the given bucket into the list
    previousBucket.next = bucket;
    bucket.prev = previousBucket;
    bucket.next.prev = bucket;
}
