import java.util.ArrayList;
import java.util.List;

/**
 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0 || start > end) {
        throw new IllegalArgumentException("Start time and end time should be non-negative and start should be less than or equal to end");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long rangeEnd = start;
    long rangeStart = start;

    while (rangeEnd < end) {
        if (rangeEnd + FETCH_DATA_DURATION > end) {
            timeRanges.add(new TimeRange(rangeStart, end));
            break;
        }
        rangeEnd += FETCH_DATA_DURATION;
        timeRanges.add(new TimeRange(rangeStart, rangeEnd - FETCH_DATA_DURATION));
        rangeStart = rangeEnd - FETCH_DATA_DURATION;
    }

    return timeRanges;
}
