public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("DayStep must be positive");
    }

    // Convert to Julia but keep the explanation
    int year = timeBucket / (1000 * 365 * 24);
    int month = (timeBucket / (1000 * 365) - year * 1000) / 30;
    int day = (timeBucket - year * 1000 * 365) - month * 30 * 24;

    int dayInBucket = day / dayStep;

    int newYear = year;
    int newMonth = month;
    int newDay = day - dayInBucket * dayStep;

    if (newDay < 0) {
        newDay += 24 * 30 * 12;
        newMonth--;
    }
    if (newMonth < 0) {
        newMonth += 12;
        newYear--;
    }

    if (newMonth == 0 && newDay == 0) {
        newMonth = 12;
        newYear--;
    }

    return (newYear * 1000 * 365 + newMonth * 30 * 24 + newDay) * dayStep;
}
