public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null) {
        throw new IllegalArgumentException("The input sequence cannot be null.");
    }
    if (str.length() <= index || index < 0) {
        throw new IndexOutOfBoundsException("Invalid index provided.");
    }
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("Slice length exceeds the string length.");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c & 0xC0) == 0x80) {
            size += 1; // Continuation byte
        } else if ((c & 0xE0) == 0xC0 || (c & 0xF0) == 0xE0) {
            size += 2; // Two-byte character
        } else if ((c & 0xF8) == 0xF0) {
            size += 3; // Three-byte character
        } else {
            size += 4; // Four-byte character
        }
    }

    return size;
}
