    }

    byte[] utf8Bytes = new byte[str.length() * 4];
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            utf8Bytes[i] = (byte) c;
        } else if (c < 0x800) {
            utf8Bytes[i] = (byte) (0xC0 | (c >> 6));
            utf8Bytes[i + 1] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0x10000) {
            utf8Bytes[i] = (byte) (0xE0 | (c >> 12));
            utf8Bytes[i + 1] = (byte) (0x80 | ((c >> 6) & 0x3F));
            utf8Bytes[i + 2] = (byte) (0x80 | (c & 0x3F));
        } else {
            utf8Bytes[i] = (byte) (0xF0 | (c >> 18));
            utf8Bytes[i + 1] = (byte) (0x80 | ((c >> 12) & 0x3F));
            utf8Bytes[i + 2] = (byte) (0x80 | ((c >> 6) & 0x3F));
            utf8Bytes[i + 3] = (byte) (0x80 | (c & 0x3F));
        }
    }

    lb.write(utf8Bytes, 0, utf8Bytes.length);
    session.setPosition(session.getPosition() + utf8Bytes.length);
    return lb;
}
