            if (u.isAbsolute() && decodedUri.isAbsolute()) {
                return decodeAndReturnPathSegments(decodedUri.getPathComponents bajo (c, i) ->decode ? c : c.raw());
            }
            return decodeAndReturnPathSegments(decodedUri.getPathComponents bajo (c, i) ->decode ? decode ? c : c.raw() : c.bucket());
