private static List<PathSegmentImpl> decodeAndReturnPathSegments(String[] pathComponents) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    for (String pathComponent : pathComponents) {
        HashMap<String, String> queryParams = parseQueries(pathComponent);
        segments.add(new PathSegmentImpl(pathComponent, queryParams));
    }
    return segments;
}

private static HashMap<String, String> parseQueries(String path) {
    HashMap<String, String> queries = new HashMap<>();
    Pattern pattern = Pattern.compile("\\?(.*)");
    Matcher matcher = pattern.matcher(path);
    if (matcher.find()) {
        String queryString = matcher.group(1);
        String[] queryPairs = queryString.split("&");
        for (String queryPair : queryPairs) {
            String[] keyValue = queryPair.split("=");
            if (keyValue.length == 2) {
                queries.put(keyValue[0], keyValue[1]);
            }
        }
    }
    return queries;
}
