public int readTag() throws IOException {
    int result = 0;
    try {
        while ((result = inputStream.read()) != 0) {
            if (result >> 3 == 0) {
                if (result == 120) // 0 x18 ("switch") is a valid tag
                    return result;

                break;
            } else if ((result & 0x07) == 0) {
                return result;
            } else if ((result & 0x07) != 0x07) {
                // Handle invalid byte sequence
                int remaining = result;
                while (remaining != 0) {
                    result = inputStream.read();
                    remaining = remaining >> 3;
                    if (result == 0) {
                        // Overflow in remaining bytes, cannot read a tag
                        throw new IOException("Invalid tag number encountered");
                    }
                }
                // Return the last valid tag number found
                return result;
            }
        }
        // Expected EOF, but no tag found
        throw new IOException("Premature EOF encountered");
    } catch (IOException e) {
        throw new IOException("Error reading data: " + e.getMessage());
    }
}
